-- ============================================================
-- Quiz coverage for cloud/architecture-patterns, cloud/cost-optimization,
-- cloud/landing-zones -- Phase 3 batch 8, the FINAL Cloud batch.
-- 60 questions total: 5 each for overview/fundamentals/intermediate/
-- advanced x 3 technologies.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- cloud/architecture-patterns/overview ----------
('cloud', 'architecture-patterns', 'overview', 'Why can two teams using the exact same cloud services (EC2, RDS, Lambda) end up with very different reliability and cost outcomes?', '["It is purely a matter of which region they deploy to", "The difference usually comes from HOW those services are arranged relative to each other -- the architecture pattern -- not which services were chosen", "Only the team with more AWS certifications gets better outcomes", "Cloud providers give better performance to accounts that spend more"]', 1, 'Architecture patterns are the reusable arrangements of the same underlying services that solve specific, recurring problems -- knowing the services is necessary but not sufficient without knowing how to arrange them for a given goal.', 'beginner'),
('cloud', 'architecture-patterns', 'overview', 'Which of these best describes the AWS Well-Architected Framework''s six pillars?', '["Six specific AWS services that must be used together", "Six evaluation lenses (Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, Sustainability) for assessing an architecture, not a single prescribed design", "A certification exam name", "A pricing tier for AWS support"]', 1, 'The pillars are a structured way to evaluate tradeoffs in a design (can you recover from failure? are you paying for what you use?) -- they are diagnostic questions, not a specific architecture to copy.', 'beginner'),
('cloud', 'architecture-patterns', 'overview', 'In Multi-AZ Active-Active, why does having both zones actively serve real traffic matter more than just having a standby?', '["It does not matter -- a cold standby is functionally identical", "An idle standby that never receives real traffic is untested in practice; active-active catches problems (stale config, unpatched dependencies) continuously instead of only during an actual failover event", "Active-Active is required by AWS''s terms of service", "It only matters for reducing AWS support costs"]', 1, 'An untested failover path is a real, common production risk -- active-active setups surface the kinds of problems that only show up under real traffic, well before an actual incident forces a failover to reveal them.', 'intermediate'),
('cloud', 'architecture-patterns', 'overview', 'What specific problem does the Strangler Fig pattern solve that a full legacy rewrite does not?', '["It makes the legacy system faster without any code changes", "It lets you migrate one capability at a time behind a routing layer, so each piece ships and is validated independently instead of betting an entire release on one big-bang rewrite", "It automatically converts legacy code to a new programming language", "It eliminates the need for the routing layer entirely"]', 1, 'The core value of Strangler Fig is de-risking migration by making it incremental and independently validated per piece, rather than a single high-risk, long-feedback-loop rewrite.', 'beginner'),
('cloud', 'architecture-patterns', 'overview', 'When would CQRS + Read Replica + Redis be the right choice according to the "Choosing the Right Pattern" guidance?', '["Whenever a service has any database at all", "For workloads with genuinely asymmetric read/write patterns -- high read traffic, low write traffic -- not as a default choice for any service with a database", "Only for services with fewer than 100 users", "Only when using MySQL specifically"]', 1, 'CQRS is justified by a real read/write asymmetry that a single data model can''t serve well for both sides -- using it without that specific driver adds complexity (eventual consistency, two data models) without the corresponding benefit.', 'intermediate'),

-- ---------- cloud/architecture-patterns/fundamentals ----------
('cloud', 'architecture-patterns', 'fundamentals', 'What is the actual problem Hub-and-Spoke networking solves as N VPCs grow?', '["VPCs become slower as more are added, regardless of connectivity", "Direct VPC-to-VPC peering becomes an unmanageable N-squared connection problem as N grows -- Hub-and-Spoke centralizes routing through one hub instead", "AWS charges more for VPCs that are not hub-connected", "It solves an IP address exhaustion problem, not a connectivity problem"]', 1, 'Without centralization, N VPCs needing to talk to each other and shared services requires roughly N-squared peering connections -- unmanageable past a handful of VPCs, and every new VPC means updating every existing one.', 'beginner'),
('cloud', 'architecture-patterns', 'fundamentals', 'In CQRS, what is the real, ongoing cost of splitting the write model from the read model?', '["There is no real cost -- CQRS is strictly an improvement with no tradeoff", "The read side becomes eventually consistent with the write side (a real, non-zero lag exists), and you are now maintaining two data models instead of one", "CQRS only works with NoSQL databases, never relational ones", "It requires rewriting the entire application in a different language"]', 1, 'This is the actual tradeoff that makes CQRS not a default choice: real eventual-consistency lag between write and read, plus the operational cost of maintaining and keeping two models in sync.', 'intermediate'),
('cloud', 'architecture-patterns', 'fundamentals', 'Why does Saga replace a traditional database transaction with a sequence of local transactions plus compensating transactions?', '["Because compensating transactions are faster to execute than a normal commit", "Because a traditional all-or-nothing transaction cannot span multiple independent microservices'' separate databases -- there is no single transaction mechanism that atomically updates two different services'' data stores together", "Because AWS does not support multi-table transactions", "Because compensating transactions are required by GDPR"]', 1, 'Once each microservice owns its own database, there genuinely is no cross-service atomic transaction available -- Saga is a deliberate accommodation to that real constraint, using compensating transactions to undo completed steps on failure instead.', 'intermediate'),
('cloud', 'architecture-patterns', 'fundamentals', 'An Availability Zone (AZ) is best described as what?', '["A logical grouping with no physical significance", "A physically separate data center (or cluster of them) within a region, with independent power, cooling, and networking -- specifically so a failure in one AZ does not correlate with a failure in another", "A backup copy of data stored in a different cloud provider", "A synonym for \"region\" -- the two terms are interchangeable"]', 1, 'The whole point of AZ separation is physical independence of power/cooling/networking, so that a large-scale failure (a power outage, hardware failure at scale) in one AZ genuinely does not take down another AZ in the same region.', 'beginner'),
('cloud', 'architecture-patterns', 'fundamentals', 'Serverless Event-Driven architecture (e.g. S3 upload triggers Lambda, stores in DynamoDB, sends SNS notification) solves what specific problem versus fixed-capacity provisioning?', '["It eliminates the need for any data storage", "Provisioning fixed capacity ahead of unpredictable, spiky load either wastes money (over-provisioned) or under-provisions (fails under a real spike) -- serverless scales from zero to the actual load automatically", "It is always cheaper than any other architecture regardless of traffic pattern", "It removes the need for any authentication or authorization"]', 1, 'The problem class this pattern solves is specifically unpredictable, spiky load where a fixed-capacity guess is likely to be wrong in one direction or the other -- serverless sidesteps the guess entirely by scaling to actual demand.', 'beginner'),

-- ---------- cloud/architecture-patterns/intermediate ----------
('cloud', 'architecture-patterns', 'intermediate', 'What is the real tradeoff between choreography and orchestration in a Saga implementation?', '["Choreography is always better regardless of saga complexity", "Choreography is simpler to start but the overall process is not visible in one place (must trace listeners across services); orchestration makes the process visible via a central coordinator, at the cost of every service now depending on that coordinator", "Orchestration cannot handle compensating transactions", "There is no meaningful difference between the two approaches"]', 1, 'This is a genuine architectural tradeoff, not a strictly-better choice: choreography scales better for a small number of simple steps, orchestration becomes clearly better once the saga has several steps or nontrivial compensation logic that benefits from central visibility.', 'advanced'),
('cloud', 'architecture-patterns', 'intermediate', 'Why is CQRS often paired with event sourcing specifically?', '["Event sourcing makes CQRS unnecessary", "Event sourcing solves CQRS''s hardest problem -- how the read side actually gets updated after a write -- by having the write side publish an event for every change that the read side subscribes to and replays into denormalized views", "They are unrelated patterns that happen to share documentation", "Event sourcing is required by law for financial applications only"]', 1, 'Event sourcing gives CQRS a concrete mechanism for keeping the read side updated (subscribing to and replaying events), plus a genuine audit log and the ability to rebuild a read view from scratch later by replaying history.', 'advanced'),
('cloud', 'architecture-patterns', 'intermediate', 'Besides the routing layer, what makes a Strangler Fig migration actually safe according to this content?', '["Nothing else is needed -- the routing layer alone is sufficient", "Shadow traffic comparison before cutover, feature-flag-controlled routing (not a hard cutover), and an explicit data-synchronization plan if legacy and new systems touch overlapping data", "Migrating 100% of traffic on day one to force adoption", "Deleting the legacy system before starting the migration"]', 1, 'A routing layer that just switches traffic is necessary but not sufficient -- shadow traffic surfaces behavioral differences before real impact, feature flags make rollback fast without a deployment, and explicit data-sync planning avoids silent data conflicts during the migration window.', 'advanced'),
('cloud', 'architecture-patterns', 'intermediate', 'Why does multi-region replication typically use asynchronous rather than synchronous replication for latency-sensitive writes?', '["Synchronous replication is not technically possible across regions at all", "Cross-region replication has meaningfully higher latency (tens to low-hundreds of ms) than cross-AZ replication (single-digit ms), which usually rules out blocking every write on a slow cross-region round trip for latency-sensitive use cases", "Asynchronous replication is always more secure than synchronous", "AWS bills synchronous cross-region replication at a much higher rate"]', 1, 'The real latency gap between cross-AZ and cross-region round trips is the deciding factor -- most multi-region setups accept a potential data-loss window from async replication rather than blocking every write on a much slower synchronous cross-region commit.', 'advanced'),
('cloud', 'architecture-patterns', 'intermediate', 'What real cost does Hub-and-Spoke networking add beyond the resources it connects?', '["No additional cost -- Transit Gateway is free", "Transit Gateway itself has per-hour and per-GB data processing charges on top of the resources it connects", "It doubles the cost of every VPC in the organization", "The cost is identical to direct VPC peering in every case"]', 1, 'Centralizing routing through a hub is not free -- the Transit Gateway itself carries its own hourly and data-processing charges, which is part of the real cost/complexity tradeoff worth weighing against the N-squared peering problem it solves.', 'intermediate'),

-- ---------- cloud/architecture-patterns/advanced ----------
('cloud', 'architecture-patterns', 'advanced', 'What specifically do circuit breakers protect, and from what?', '["They protect the failing dependency from receiving any future traffic ever again", "They protect the CALLER''s own resources (threads, connections) from being exhausted waiting on a struggling dependency, by failing fast after a threshold of repeated failures instead of waiting out slow timeouts", "They protect against SQL injection attacks", "They are a networking-layer firewall rule"]', 1, 'The point of a circuit breaker is specifically to stop the caller from exhausting its own resources on a dependency that is clearly unhealthy, while also giving that dependency room to recover instead of continued load while degraded.', 'advanced'),
('cloud', 'architecture-patterns', 'advanced', 'In multi-region active-active, what does "split-brain handling" during a network partition actually require deciding?', '["Whether to shut down both regions simultaneously", "Whether each region keeps serving writes independently during the partition (risking conflicting state to reconcile later) or one region stops accepting writes (sacrificing availability for consistency) -- a concrete instance of the CAP theorem tradeoff", "Which programming language to use for the application", "How many Availability Zones each region should have"]', 1, 'This is CAP theorem made concrete rather than theoretical -- a real architectural decision about availability vs. consistency that needs to be made deliberately ahead of time, not discovered for the first time during an actual partition.', 'advanced'),
('cloud', 'architecture-patterns', 'advanced', 'Why do production-grade Saga implementations specifically require each step to be idempotent?', '["Idempotency makes the code shorter to write", "Most real message brokers guarantee at-least-once delivery, not exactly-once -- meaning a step can receive the same event twice, and idempotency ensures processing it twice produces the same result as processing it once, not a duplicate side effect", "Idempotent steps run faster than non-idempotent ones", "It is only relevant for financial transactions, not other Saga use cases"]', 1, 'At-least-once delivery is the realistic guarantee most message infrastructure actually provides -- idempotency is what prevents a duplicate delivery from causing a duplicate real-world effect (like charging a customer twice).', 'advanced'),
('cloud', 'architecture-patterns', 'advanced', 'What does adding a new read model to an event-sourced CQRS system actually require, once the system is already event-sourced?', '["Re-architecting the entire write side to support the new access pattern", "Subscribing a new consumer to the existing event stream and building its view from replaying that history -- the write side does not need to change", "Migrating all existing data to a new database engine", "Adding the new read model is not possible after the initial design"]', 1, 'This is exactly the value event sourcing unlocks for CQRS at advanced scale: because every historical change is preserved as replayable events, a genuinely new read model can be built later by consuming that existing stream, without touching the write side.', 'advanced'),
('cloud', 'architecture-patterns', 'advanced', 'What is the actual purpose of an Architecture Decision Record (ADR)?', '["A complete technical specification of the entire system", "A short, version-controlled document capturing one specific decision, the alternatives considered, and the reasoning behind it -- written at the time the decision is made, not exhaustive system documentation", "A legal contract between engineering teams", "A performance benchmark report"]', 1, 'ADRs exist specifically to preserve the WHY behind a decision (why CQRS here, why Saga uses orchestration there) at the time it''s made, since that context is otherwise easily lost once a system has accumulated several such decisions.', 'advanced'),

-- ---------- cloud/cost-optimization/overview ----------
('cloud', 'cost-optimization', 'overview', 'Why does cloud spending tend to accumulate as invisible waste more easily than traditional infrastructure spending?', '["Cloud providers deliberately hide costs from customers", "Launching a bigger instance or leaving one running costs nothing to DO immediately -- the cost only becomes visible later on the monthly bill, unlike buying physical hardware which has an immediate, obvious cost", "Cloud instances are always more expensive than physical servers", "There is no way to ever see cloud costs before the bill arrives"]', 1, 'The lack of an immediate feedback loop is the core problem FinOps addresses -- nothing about launching or forgetting to terminate a resource gives instant cost feedback the way an upfront hardware purchase would.', 'beginner'),
('cloud', 'cost-optimization', 'overview', 'What does an unattached EBS volume found via `aws ec2 describe-volumes --filters Name=status,Values=available` represent?', '["A volume that is currently in active use by a running instance", "Storage that is being billed but is not attached to (and therefore not doing anything useful for) any instance", "A volume that AWS provides for free", "A volume that has already been deleted"]', 1, 'An \"available\" status specifically means the volume is not attached to any instance -- it is a classic waste category: paying for storage capacity that is not serving any workload.', 'beginner'),
('cloud', 'cost-optimization', 'overview', 'What does AWS Compute Optimizer analyze to recommend smaller instance types?', '["The instance''s purchase price only", "CloudWatch metrics reflecting actual utilization (CPU, memory) over time, to identify instances sized well beyond what they actually use", "The number of days since the instance was launched", "The AWS region the instance is deployed in"]', 1, 'Compute Optimizer''s recommendations are grounded in actual observed usage data, not guesswork -- that''s what makes a downsizing recommendation evidence-based rather than a blind guess.', 'beginner'),
('cloud', 'cost-optimization', 'overview', 'What is the practical difference between Reserved Instances and Compute Savings Plans?', '["They are identical products with different names", "Reserved Instances commit to a specific instance type/family for a discount; Compute Savings Plans commit to a dollar amount per hour of compute, flexibly applying to any EC2/Fargate/Lambda usage -- generally the more flexible, often-recommended option", "Reserved Instances are always cheaper than Savings Plans in every scenario", "Savings Plans can only be purchased for a 3-year term"]', 1, 'The flexibility difference is the key practical distinction -- Savings Plans apply the commitment across instance types and even compute services, while RIs lock in a specific instance type, making Savings Plans generally more adaptable to changing workloads.', 'intermediate'),
('cloud', 'cost-optimization', 'overview', 'Why are Spot Instances specifically recommended for batch processing and CI/CD runners rather than production web servers?', '["Spot Instances are technically incapable of running web server software", "Spot Instances can be interrupted with only a short notice window, which fault-tolerant/interruptible workloads (batch jobs, CI/CD) can absorb but a production web server serving live user requests generally cannot without added interruption-handling complexity", "Spot Instances are more expensive than On-Demand for web workloads specifically", "CI/CD runners are legally required to use Spot Instances"]', 1, 'The interruption risk is the deciding factor -- workloads that can gracefully handle being interrupted and restarted elsewhere are a good fit for the steep discount; workloads serving live traffic without that tolerance are a much riskier fit.', 'beginner'),

-- ---------- cloud/cost-optimization/fundamentals ----------
('cloud', 'cost-optimization', 'fundamentals', 'Why is tagging described as a prerequisite for the other three cost-optimization pillars, rather than a separate optional pillar?', '["Tagging is required by AWS''s terms of service", "Without consistent tags, you can see the total bill but cannot attribute spend to a specific team or project -- right-sizing, pricing-model choice, and waste removal all need to know WHO a resource belongs to in order to act on it", "Tagging automatically reduces costs on its own without any other action", "Tags are only relevant for compliance audits, not cost management"]', 1, 'The analogy given is a household grocery bill with no idea which family member bought what -- you can still cut the total, but you can''t find the actual, attributable waste without first being able to attribute spend to a source.', 'intermediate'),
('cloud', 'cost-optimization', 'fundamentals', 'What does `aws ce get-cost-and-usage --group-by Type=DIMENSION,Key=SERVICE` actually show you?', '["A list of every individual resource and its exact real-time cost", "Cost and usage data grouped by AWS service (e.g. EC2, S3, RDS), over the specified time period and granularity", "A forecast of next month''s bill", "The physical AWS data center location for each resource"]', 1, 'This Cost Explorer query breaks down spend by which AWS service it came from -- useful for seeing where money is going at a high level, though it does not by itself tell you WHICH team or project within that service is responsible without tag-based grouping.', 'beginner'),
('cloud', 'cost-optimization', 'fundamentals', 'What is the actual function of Trusted Advisor''s "cost_optimizing" category checks?', '["It automatically deletes any resource it finds", "It surfaces specific cost-optimization findings (like the query `aws support describe-trusted-advisor-checks --query \'checks[?category==`cost_optimizing`]\'` retrieves) for a human to review and act on", "It only works for AWS Enterprise Support customers, with zero functionality for other support tiers", "It replaces the need for Cost Explorer entirely"]', 1, 'Trusted Advisor''s checks surface specific, actionable findings across categories including cost optimization -- it is a recommendation source, not an automated remediation tool that acts without review.', 'intermediate'),
('cloud', 'cost-optimization', 'fundamentals', 'According to the Four Pillars framework, what distinguishes "Architecture" from the other three pillars (Right-Sizing, Pricing Model, Waste Removal)?', '["Architecture is not actually a real cost-optimization technique", "Architecture is about designing for cost efficiency from the start, which reduces how urgently the other three reactive pillars are needed going forward, rather than being another reactive cleanup action", "Architecture only applies to serverless workloads", "The other three pillars are optional once Architecture is addressed"]', 1, 'The other three pillars are largely about identifying and correcting existing waste or mis-provisioning; Architecture is the proactive pillar that reduces how much of that reactive work accumulates in the first place.', 'intermediate'),
('cloud', 'cost-optimization', 'fundamentals', 'Why does finding unattached EBS volumes via the CLI matter as a first practical exercise for someone new to cost optimization?', '["It is the only waste category that actually costs money", "It demonstrates the core, recurring FinOps problem directly -- cost that accumulates silently with no natural prompt to notice it, since even personal free-tier accounts often have leftover unattached volumes from terminated instances", "EBS volumes are the single most expensive AWS resource type", "The command only works in production accounts, never sandbox accounts"]', 1, 'The exercise is designed to make the page''s central theme -- invisible-until-you-look waste -- concrete and immediate, using a resource type common enough that even a small personal account usually has at least one example.', 'beginner'),

-- ---------- cloud/cost-optimization/intermediate ----------
('cloud', 'cost-optimization', 'intermediate', 'What does `aws savingsplans describe-savings-plans-purchase-recommendation` require as input to generate a meaningful recommendation?', '["Nothing -- it works identically regardless of parameters", "Parameters like savings-plan-type, term-in-years, payment-option, and a lookback-period (e.g. 60 days) of actual usage history to base the recommendation on", "A credit card number entered directly into the CLI command", "The specific EC2 instance IDs to be replaced"]', 1, 'Savings Plans recommendations are grounded in actual historical usage over the specified lookback period -- the parameters shape which commitment type and term the recommendation engine evaluates against that real usage data.', 'intermediate'),
('cloud', 'cost-optimization', 'intermediate', 'Why does the scheduled stop/start pattern for dev/staging instances (stop at night, start in the morning on weekdays) produce real savings?', '["It reduces the instance''s hourly rate permanently", "Compute billing is generally by the hour/second an instance is actually running -- stopping instances outside business hours means you are not billed for compute time when nobody is using them", "It only saves money on storage costs, not compute", "AWS gives a discount specifically for using EventBridge schedules"]', 1, 'This is a straightforward consequence of usage-based billing: an instance stopped overnight and on weekends simply is not accruing compute charges during that stopped time, which adds up meaningfully for non-production environments that don''t need 24/7 uptime.', 'intermediate'),
('cloud', 'cost-optimization', 'intermediate', 'What is the purpose of S3 Intelligent-Tiering compared to manually-configured lifecycle policies?', '["It is identical to a lifecycle policy with a different name", "Intelligent-Tiering automatically monitors access patterns and moves objects between tiers without needing to predict or configure a fixed schedule upfront, unlike a lifecycle policy which transitions objects on a fixed time-based schedule regardless of actual access", "It only works for objects smaller than 1KB", "It requires manually moving each object individually"]', 1, 'The key difference is automatic, access-pattern-driven tiering versus a fixed schedule -- Intelligent-Tiering is well-suited for data whose access pattern is unpredictable or changes over time, where a fixed lifecycle rule might move data too early or too late.', 'intermediate'),
('cloud', 'cost-optimization', 'intermediate', 'What information does the S3 storage-class-analysis export actually provide?', '["The exact contents of every object in the bucket", "Data supporting a decision about which objects could move to a cheaper storage tier, based on observed access patterns", "A list of IAM users who have accessed the bucket", "The geographic replication status of the bucket"]', 1, 'Storage class analysis is specifically an input to a tiering decision -- it tells you which objects are good/bad candidates for cheaper tiers based on how they''re actually being accessed, not their content or access-control configuration.', 'intermediate'),
('cloud', 'cost-optimization', 'intermediate', 'Why would a team use `get-rightsizing-recommendation` from Cost Explorer in addition to Compute Optimizer''s recommendations?', '["The two tools are mutually exclusive and cannot be used together", "Cost Explorer''s rightsizing recommendation can factor in commitment-based benefits already applied (BenefitsConsidered), giving a different, complementary view alongside Compute Optimizer''s utilization-based findings", "Compute Optimizer only works for RDS, never EC2", "get-rightsizing-recommendation replaces the need for any utilization data entirely"]', 1, 'These are complementary rather than redundant tools -- cross-referencing multiple sources of right-sizing evidence (utilization-based from Compute Optimizer, benefit-aware from Cost Explorer) gives a more complete picture than relying on just one.', 'advanced'),

-- ---------- cloud/cost-optimization/advanced ----------
('cloud', 'cost-optimization', 'advanced', 'What does an AWS Config Rule like "required-tags" actually enforce?', '["It automatically adds the required tags to any resource missing them", "It flags resources as non-compliant if they are missing specified required tags (e.g. Environment, Owner, Project), for visibility and audit -- it does not by itself create the missing tags", "It prevents any resource from being created at all, tagged or not", "It only applies to S3 buckets, not other resource types"]', 1, 'A Config Rule is a detective control -- it surfaces non-compliance for review/action, which is a different mechanism from a preventive control that would block resource creation outright.', 'advanced'),
('cloud', 'cost-optimization', 'advanced', 'In the AWS Budgets example with a threshold-based notification, what does `"Threshold":80,"ThresholdType":"PERCENTAGE"` actually trigger?', '["A notification only after the budget is exceeded by 80% additional spend", "A notification when actual spend reaches 80% of the defined budget limit, intended to alert before the full budget is exhausted, not after", "An automatic budget increase of 80%", "A notification exactly 80 days after budget creation"]', 1, 'Percentage-based budget thresholds are designed to give advance warning as spend approaches the limit -- 80% is a common choice specifically because it leaves room to act before the team fully exhausts (or exceeds) their allocation.', 'advanced'),
('cloud', 'cost-optimization', 'advanced', 'Why does the Spot Fleet example specify multiple instance types with `AllocationStrategy: diversified` rather than requesting a single instance type?', '["Diversification is required by AWS for all Spot requests", "Spreading a fleet across multiple instance types/pools makes the fleet more resilient to Spot capacity/interruption in any single pool, since not all pools are likely to be reclaimed simultaneously", "It reduces the per-instance price below the specified SpotPrice cap", "It guarantees the fleet will never be interrupted"]', 1, 'Diversifying across instance types is a resilience strategy against Spot interruption -- if AWS reclaims capacity in one instance-type pool, the fleet can continue running on capacity from the other pools rather than losing the entire fleet at once.', 'advanced'),
('cloud', 'cost-optimization', 'advanced', 'What must a Spot Fleet application do in response to the 2-minute interruption warning available via instance metadata?', '["Nothing -- Spot interruptions cannot be detected in advance", "Poll the instance metadata endpoint for the interruption notice and use that short window to checkpoint work, drain connections, or otherwise gracefully wind down before the actual reclaim happens", "Immediately terminate all other instances in the fleet", "Automatically switch the account to On-Demand pricing"]', 1, 'The interruption-warning mechanism exists specifically so fault-tolerant applications can use the notice window productively -- saving progress or draining gracefully -- rather than losing in-progress work abruptly when Spot capacity is reclaimed.', 'advanced'),
('cloud', 'cost-optimization', 'advanced', 'Why is cost-allocation tagging enabled separately in the billing console (via `update-cost-allocation-tags-status`) in addition to just applying tags to resources?', '["Tags on resources are automatically billing-visible with no separate step required", "AWS requires cost-allocation tags to be explicitly activated in Billing before they become available as a grouping dimension in Cost Explorer -- applying a tag to a resource alone does not make it usable for cost breakdown", "This step is only required for GCP, not AWS", "It permanently locks the tag value and prevents future changes"]', 1, 'This is a genuinely easy-to-miss two-step process -- a resource can be correctly tagged and still not show up grouped by that tag in Cost Explorer until the tag is separately activated for cost allocation in the billing console.', 'advanced'),

-- ---------- cloud/landing-zones/overview ----------
('cloud', 'landing-zones', 'overview', 'What real problem does a landing zone solve that a single shared cloud account does not?', '["It makes cloud resources run faster", "A single shared account means one shared blast radius -- a dev team''s mistake can touch prod resources, there is no clean cost visibility per team, and a security incident in one project can potentially reach everything else", "It eliminates the need for any IAM permissions at all", "It is only relevant for companies with more than 1000 employees"]', 1, 'The core motivation is isolating blast radius and enabling per-team visibility and guardrails BEFORE a second team or production workload makes the shared-account problems obvious the hard way.', 'beginner'),
('cloud', 'landing-zones', 'overview', 'In the AWS Control Tower account structure, what is the specific purpose of the Log Archive account?', '["It runs the organization''s production workloads", "It centrally receives and stores logs (e.g. CloudTrail, Config) from across the organization, so log data is not scattered per-account and is protected from being altered/deleted by whoever caused the activity being logged", "It is where developers write and test new application code", "It is a billing-only account with no other function"]', 1, 'Centralizing logs into a dedicated account is a deliberate security design -- it separates the audit trail from the accounts being audited, so someone with access to a workload account cannot also tamper with the logs recording their own activity there.', 'intermediate'),
('cloud', 'landing-zones', 'overview', 'What is the practical difference between a preventive guardrail (SCP) and a detective guardrail (Config Rule)?', '["They are two names for the exact same mechanism", "A preventive guardrail (SCP) blocks a non-compliant action from happening at all; a detective guardrail (Config Rule) flags/alerts on a violation after it has already occurred", "Detective guardrails are always stricter than preventive ones", "SCPs can only be applied to individual resources, never whole accounts"]', 1, 'This is a meaningful architectural distinction -- SCPs stop the action outright (e.g. denying an API call), while Config Rules observe existing state and flag deviations, which is a fundamentally different enforcement point in the lifecycle.', 'intermediate'),
('cloud', 'landing-zones', 'overview', 'Why is Account Factory''s self-service account vending described as valuable beyond just saving manual effort?', '["It is not actually valuable -- manual account creation is equally good", "New accounts are automatically provisioned with the standard guardrails already applied, avoiding a gap where an account exists but is not yet governed by the organization''s baseline controls", "It eliminates the need for AWS Organizations entirely", "It only works for Azure subscriptions, not AWS accounts"]', 1, 'The key value beyond convenience is consistency and closing the "ungoverned gap" -- a manually-created account can sit unguarded until someone remembers to apply guardrails; automated vending applies them from the moment the account exists.', 'intermediate'),
('cloud', 'landing-zones', 'overview', 'Why does the "Restrict Regions" SCP example explicitly exclude actions like `iam:*`, `organizations:*`, and `sts:*` from the region restriction?', '["Those services are being deprecated by AWS", "Those are global services that either operate outside any single region or need to remain callable regardless of the RequestedRegion condition for the account to keep functioning correctly (e.g. IAM management, STS for assuming roles)", "It is a mistake in the policy that should be removed", "Global services are automatically exempt from all SCPs with no explicit exclusion needed"]', 1, 'Global/foundational AWS services need to remain usable regardless of a region restriction meant to constrain where WORKLOADS run -- blocking IAM or STS entirely via an overly broad region SCP would break basic account functionality, not just restrict workload placement.', 'advanced'),

-- ---------- cloud/landing-zones/fundamentals ----------
('cloud', 'landing-zones', 'fundamentals', 'Why are landing zones described as "infrastructure for infrastructure"?', '["They only apply to physical data centers, not cloud", "Everything else in a cloud deployment (VMs, networking, databases) assumes a well-organized account/subscription to deploy into -- landing zones are the layer of decisions (account structure, guardrails, identity) that need to exist before any of that", "They are a marketing term with no real technical meaning", "They replace the need for VPCs and networking entirely"]', 1, 'The framing is deliberate: a landing zone is the foundational layer that has to be decided and built first, because retrofitting account structure and guardrails onto an already-sprawling, ungoverned set of accounts is dramatically harder than starting with them in place.', 'beginner'),
('cloud', 'landing-zones', 'fundamentals', 'What is the functional equivalent of an AWS Organizational Unit (OU) in the Azure Management Group hierarchy?', '["An Azure Resource Group", "An Azure Management Group (MG) -- both provide a way to organize accounts/subscriptions hierarchically and apply policies at that grouping level rather than per-account", "An Azure Availability Zone", "There is no Azure equivalent to an AWS OU"]', 1, 'Both AWS OUs and Azure Management Groups exist to organize accounts/subscriptions by function (platform, workloads, sandbox) and apply policy at the group level -- the underlying concept (separation by function and blast-radius) transfers directly even though the vendor-specific names differ.', 'intermediate'),
('cloud', 'landing-zones', 'fundamentals', 'In the recommended AWS Organizations structure, why are Production and Non-Production kept as separate OUs under Workloads, rather than one combined Workloads OU?', '["AWS technically requires this separation by default", "Separating them allows different, appropriately stricter guardrails (SCPs) to be applied to Production specifically, without either loosening controls on Prod to match Non-Prod or over-restricting Non-Prod to match Prod''s stricter needs", "It has no functional purpose, only cosmetic organization", "Non-Production accounts are billed differently by AWS based on OU placement"]', 1, 'The separation exists specifically so policy (SCPs, guardrails) can differ appropriately between environments with very different risk profiles -- a single combined OU would force one policy level onto both, which is rarely the right tradeoff for either.', 'intermediate'),
('cloud', 'landing-zones', 'fundamentals', 'What does "Account Factory for Terraform (AFT)" specifically add on top of plain AWS Control Tower?', '["It replaces Control Tower entirely with a different service", "It provides a GitOps-based workflow for account vending -- account requests and configuration are managed as code/PRs, rather than only through the Control Tower console''s Account Factory UI", "It is only used for billing reconciliation, not account creation", "It removes the need for any guardrails on new accounts"]', 1, 'AFT layers a GitOps workflow (account requests as code, reviewed via PR, applied via pipeline) on top of Control Tower''s account-provisioning capability -- useful for teams that want account creation to go through the same review/audit process as other infrastructure changes.', 'advanced'),
('cloud', 'landing-zones', 'fundamentals', 'Why does the Study Resources section point to the Cloud Adoption Framework from all three major providers (AWS, Azure, GCP) rather than just one?', '["Only one of the three actually has a published framework", "Landing zone concepts are largely provider-agnostic, and comparing the frameworks side by side (as suggested in this page''s own exercises) reinforces which parts of the design are universal versus vendor-specific naming", "The frameworks are identical documents republished under different names", "It is only relevant for multi-cloud deployments, never single-cloud"]', 1, 'Even for a single-cloud deployment, seeing how the same underlying concepts (guardrails, account separation, identity centralization) are expressed across multiple providers'' frameworks helps distinguish the transferable concept from the vendor-specific terminology.', 'intermediate'),

-- ---------- cloud/landing-zones/intermediate ----------
('cloud', 'landing-zones', 'intermediate', 'What is the functional difference between `controltower list-enabled-controls` and `controltower enable-control`?', '["They are aliases for the exact same operation", "list-enabled-controls queries which controls (guardrails) are currently active on a target OU/account; enable-control activates an additional specific control on that target", "enable-control only works on the management account, never on OUs", "list-enabled-controls modifies controls, while enable-control only reads them"]', 1, 'One is a read operation (what''s currently enabled) and the other is a write operation (turn on a specific additional control) -- a common pattern of checking current state before deliberately changing it.', 'intermediate'),
('cloud', 'landing-zones', 'intermediate', 'In the "PreventLeavingOrg" SCP, why is the Resource field set to `"*"` rather than a specific resource ARN?', '["It is a syntax error that should be a specific ARN", "The organizations:LeaveOrganization action does not target a specific resource ARN in the way an S3 or EC2 action would -- it is an account-level action the wildcard correctly represents", "Wildcards are required by AWS for all SCP statements regardless of action", "It intentionally applies the deny to every AWS service, not just Organizations"]', 1, 'organizations:LeaveOrganization is an account-level action without a specific addressable resource the way, say, an S3 object action would have -- the wildcard here is the correct, standard way to express \"this action, regardless of resource context.\"', 'advanced'),
('cloud', 'landing-zones', 'intermediate', 'What would happen if the "RestrictRegions" SCP''s NotAction exclusion list did not include `sts:*`?', '["Nothing -- STS is unrelated to region restrictions", "Cross-account role assumption (which relies on STS) could be blocked in non-allowed regions, potentially breaking legitimate access patterns that depend on assuming roles regardless of the calling region", "The SCP would fail to save entirely", "It would only affect billing, not actual permissions"]', 1, 'STS underlies role-assumption flows used throughout AWS Organizations (including cross-account access patterns landing zones rely on) -- excluding it from a region restriction avoids inadvertently breaking those flows for calls originating outside the allowed regions.', 'advanced'),
('cloud', 'landing-zones', 'intermediate', 'Why does the "PreventDisablingSecurityServices" SCP explicitly deny actions like `cloudtrail:StopLogging` and `guardduty:DeleteDetector`?', '["These actions are deprecated and no longer functional in AWS anyway", "Without this guardrail, an account with sufficient IAM permissions could disable the very security/audit tooling meant to detect and log suspicious activity -- defeating the landing zone''s security baseline from within a member account", "It has no security purpose, only a cost-control purpose", "These actions are already blocked by AWS globally regardless of any SCP"]', 1, 'This is a defense-in-depth guardrail: even if an account has broad IAM permissions, this SCP prevents that access from being used to blind the organization''s own security monitoring -- a real, meaningful gap without this specific denial.', 'advanced'),
('cloud', 'landing-zones', 'intermediate', 'What does Control Tower''s Account Factory (configured via Service Catalog) actually output when a team requests a new account?', '["Only an empty AWS account with no further configuration", "A new account pre-configured with SSO access, CloudTrail, Config, GuardDuty, and Security Hub already enabled -- not a bare account requiring manual security setup afterward", "A read-only account that cannot deploy any resources", "A shared account used by multiple teams simultaneously"]', 1, 'The value of Account Factory is that the resulting account already has the organization''s security/logging baseline applied from creation, rather than existing in an unguarded state until someone manually configures it afterward.', 'intermediate'),

-- ---------- cloud/landing-zones/advanced ----------
('cloud', 'landing-zones', 'advanced', 'In the Terraform landing-zone module example, what is the purpose of the `excluded_accounts` parameter set to the management account ID?', '["It marks the management account for deletion", "It prevents the baseline configuration (guardduty_admin, config_recorder, security_hub via StackSets) intended for member/workload accounts from being incorrectly applied to the management account itself, which typically has different, more restricted handling", "It has no functional effect, only documentation value", "It grants the management account extra permissions beyond other accounts"]', 1, 'The management account is architecturally special (it''s the root of the organization) and generally should not receive the same StackSet-deployed baseline as ordinary member accounts -- excluding it explicitly avoids misapplying workload-account configuration to the org root.', 'advanced'),
('cloud', 'landing-zones', 'advanced', 'Why is a Transit Gateway shared via AWS RAM (Resource Access Manager) to the whole organization, rather than each spoke account creating its own Transit Gateway?', '["RAM sharing is required by AWS and cannot be avoided", "A single shared Transit Gateway in the network account, shared out via RAM, avoids duplicating the hub itself per account and keeps routing genuinely centralized -- creating per-account TGWs would recreate the N-to-N complexity Hub-and-Spoke is meant to eliminate", "RAM sharing makes the Transit Gateway free of charge", "Each account creating its own TGW would be functionally identical to sharing one"]', 1, 'The whole point of Hub-and-Spoke is ONE central hub -- sharing a single Transit Gateway via RAM to spoke accounts preserves that centralization; letting each account create its own would undermine the pattern entirely and reintroduce the complexity it exists to avoid.', 'advanced'),
('cloud', 'landing-zones', 'advanced', 'What does the centralized egress pattern (spoke VPC -> TGW -> inspection VPC -> AWS Network Firewall -> NAT GW -> internet) achieve that per-VPC NAT Gateways do not?', '["It makes internet access faster for every spoke account", "It routes all outbound internet traffic from every spoke through one inspected, centrally-managed path, enabling organization-wide traffic inspection and a single point of egress control, rather than each VPC having its own uninspected NAT path", "It eliminates the need for any Transit Gateway at all", "It only works for inbound traffic, not outbound"]', 1, 'Centralizing egress through one inspection point is specifically about visibility and control -- every spoke''s outbound traffic passes through the same firewall/inspection layer, which per-VPC NAT Gateways (each with its own uninspected path) would not provide.', 'advanced'),
('cloud', 'landing-zones', 'advanced', 'Why does the `aws_servicecatalog_product` resource in the Terraform example reference a CloudFormation template URL for the account-vending product, even though the surrounding module is otherwise Terraform?', '["This is a bug -- Service Catalog only supports Terraform-native definitions", "AWS Service Catalog products are natively defined via CloudFormation templates; using Terraform to manage the Service Catalog product resource itself (which then references a CloudFormation-based provisioning artifact) is how Terraform and Service Catalog''s CloudFormation-based product model actually interoperate", "The CloudFormation template is unused dead configuration", "It indicates the account vending feature does not actually work"]', 1, 'This reflects a real interoperability pattern -- Service Catalog''s provisioning-artifact mechanism is CloudFormation-based at the AWS API level, so a Terraform-managed Service Catalog product legitimately still references a CloudFormation template as its actual provisioning artifact.', 'advanced'),
('cloud', 'landing-zones', 'advanced', 'What real gap does a self-service account-vending pipeline (Project 3''s design) close that manual account creation leaves open?', '["It eliminates the need for any guardrails whatsoever", "The gap between an account being created and guardrails actually being applied to it -- automated vending attaches the account to the correct OU (inheriting its SCPs) and applies baseline Terraform as part of the same pipeline, rather than as a manual follow-up step someone might delay or forget", "It removes the need for a Log Archive account", "It only works for Azure subscriptions, not AWS accounts"]', 1, 'The core value being tested here is closing the ungoverned-gap window -- a manually-provisioned account can sit without its intended guardrails until someone gets around to applying them; a properly designed pipeline applies OU placement and baseline configuration atomically with account creation.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
